import numpy as np

def logistic(t, p0, K, k):
    """P(t) for P' = kP(1 - P/K), P(0) = p0. t may be an array."""
    t = np.asarray(t, dtype=float)
    return K / (1 + (K - p0) / p0 * np.exp(-k * t))

def time_to_fraction(p0, K, k, frac):
    """Time for P to reach frac * K. ValueError unless p0/K <= frac < 1."""
    if not (p0 / K <= frac < 1):
        raise ValueError("frac must lie between p0/K and 1")
    return float(np.log(frac * (K - p0) / ((1 - frac) * p0)) / k)
